ALTER TABLE public.notifications ADD COLUMN IF NOT EXISTS chat_message_id uuid REFERENCES public.messages(id) ON DELETE CASCADE;
CREATE UNIQUE INDEX IF NOT EXISTS one_notice_per_chat_message ON public.notifications(chat_message_id) WHERE chat_message_id IS NOT NULL;
CREATE OR REPLACE FUNCTION public.guard_chat_notice() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND NEW.chat_message_id IS DISTINCT FROM OLD.chat_message_id THEN RAISE EXCEPTION 'CHAT_NOTICE_PROTECTED'; END IF; IF NEW.chat_message_id IS NOT NULL AND (NOT EXISTS(SELECT 1 FROM public.messages m WHERE m.id=NEW.chat_message_id AND m.receiver_id=NEW.user_id AND NOT m.is_auto AND m.app_call_id IS NULL) OR (TG_OP='INSERT' AND coalesce(current_setting('app.chat_notice',true),'')<>NEW.chat_message_id::text)) THEN RAISE EXCEPTION 'CHAT_NOTICE_PROTECTED'; END IF; RETURN NEW; END $$;
CREATE TRIGGER a_chat_notice_guard BEFORE INSERT OR UPDATE ON public.notifications FOR EACH ROW EXECUTE FUNCTION public.guard_chat_notice();
CREATE OR REPLACE FUNCTION public.notify_incoming_chat_message() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE previous text:=coalesce(current_setting('app.chat_notice',true),''); BEGIN IF NEW.is_auto OR NEW.app_call_id IS NOT NULL OR NEW.sender_id=NEW.receiver_id OR NOT public.account_allowed(NEW.sender_id) OR NOT public.account_allowed(NEW.receiver_id) THEN RETURN NEW; END IF; PERFORM set_config('app.chat_notice',NEW.id::text,true); INSERT INTO public.notifications(user_id,message,chat_message_id) VALUES(NEW.receiver_id,'మీకు కొత్త సందేశం వచ్చింది; సంభాషణలో చూడండి.',NEW.id) ON CONFLICT DO NOTHING; PERFORM set_config('app.chat_notice',previous,true); RETURN NEW; END $$;
CREATE TRIGGER incoming_chat_notice AFTER INSERT ON public.messages FOR EACH ROW EXECUTE FUNCTION public.notify_incoming_chat_message();
CREATE OR REPLACE FUNCTION public.notification_delivery_allowed(_user uuid,_notice uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT (auth.uid()=_user OR auth.role()='service_role') AND (public.paid_alert_ready(_user) OR EXISTS(SELECT 1 FROM public.free_work_notice_queue WHERE user_id=_user AND notification_id=_notice)) AND EXISTS(SELECT 1 FROM public.notifications n WHERE n.id=_notice AND n.user_id=_user AND (n.chat_message_id IS NULL OR EXISTS(SELECT 1 FROM public.messages m WHERE m.id=n.chat_message_id AND m.receiver_id=_user AND public.account_allowed(m.sender_id) AND public.account_allowed(m.receiver_id))) AND (NOT n.vehicle_bell OR (public.has_paid_bell(_user) AND public.bell_route_within_radius(n.post_id,n.bell_demand,n.bell_actor))) AND (NOT EXISTS(SELECT 1 FROM public.posts p WHERE p.id IN(n.post_id,n.matched_post_id) AND p.module='vehicle') OR (public.has_paid_bell(_user) AND EXISTS(SELECT 1 FROM public.posts p WHERE p.id IN(n.post_id,n.matched_post_id) AND p.module='vehicle' AND public.bell_route_within_radius(p.id,NULL,_user))))); $$;